const text = (key, fallback = '') => typeof $json[key] === 'string' ? $json[key].trim() : fallback;
const lower = (key, fallback) => {
  const value = text(key);
  return value === '' ? fallback : value.toLowerCase();
};
const sessionId = text('sessionId');
const contactName = text('contactName');
const company = text('company');
const offer = text('offer');
const source = lower('source', 'other');
const enquiryDate = text('enquiryDate');
const lostDate = text('lostDate');
const competitorsPresent = lower('competitorsPresent', 'unknown');
const competitorNotes = text('competitorNotes');
const statedConcerns = text('statedConcerns');
const lossReasonsRaw = lower('lossReasons', 'unknown');
const doorOpen = lower('doorOpen', 'unknown');
const nextTouch = text('nextTouch');
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const datePattern = /^\d{4}-\d{2}-\d{2}$/;
const sources = ['web-form', 'referral', 'outreach', 'repeat-client', 'other'];
const yesNoUnknown = ['yes', 'no', 'unknown'];
const reasonList = ['price', 'timing', 'location', 'scope', 'relationship', 'in-house', 'unknown'];
const lossReasons = lossReasonsRaw.split(',').map((value) => value.trim()).filter(Boolean);
const validDate = (value) => datePattern.test(value) && !Number.isNaN(Date.parse(`${value}T00:00:00Z`));
const proposedInput = {
  contactName, company, offer, source, enquiryDate, lostDate,
  competitorsPresent, competitorNotes, statedConcerns,
  lossReasons: lossReasons.join(','), doorOpen, nextTouch
};
let error = null;

if (!uuidPattern.test(sessionId)) {
  error = { code: 'INVALID_SESSION', message: 'The lost-lead proposal needs a valid conversation session.' };
} else if (contactName.length === 0 || contactName.length > 80) {
  error = { code: 'INVALID_CONTACT', message: 'Contact name is required and must be 80 characters or fewer.' };
} else if (company.length === 0 || company.length > 120) {
  error = { code: 'INVALID_COMPANY', message: 'Company is required and must be 120 characters or fewer.' };
} else if (offer.length === 0 || offer.length > 200) {
  error = { code: 'INVALID_OFFER', message: 'The offer summary is required and must be 200 characters or fewer.' };
} else if (!sources.includes(source)) {
  error = { code: 'INVALID_SOURCE', message: `Source must be one of: ${sources.join(', ')}.` };
} else if (!validDate(enquiryDate)) {
  error = { code: 'INVALID_ENQUIRY_DATE', message: 'Enquiry date must use YYYY-MM-DD.' };
} else if (!validDate(lostDate)) {
  error = { code: 'INVALID_LOST_DATE', message: 'Lost date must use YYYY-MM-DD.' };
} else if (lostDate < enquiryDate) {
  error = { code: 'INVALID_DATE_ORDER', message: 'The lost date cannot be before the enquiry date.' };
} else if (!yesNoUnknown.includes(competitorsPresent)) {
  error = { code: 'INVALID_COMPETITORS', message: 'Competitors present must be yes, no, or unknown.' };
} else if (competitorNotes.length > 500) {
  error = { code: 'NOTES_TOO_LONG', message: 'Competitor notes must be 500 characters or fewer.' };
} else if (statedConcerns.length > 500) {
  error = { code: 'CONCERNS_TOO_LONG', message: 'Stated concerns must be 500 characters or fewer.' };
} else if (lossReasons.length === 0 || !lossReasons.every((reason) => reasonList.includes(reason))) {
  error = { code: 'INVALID_REASONS', message: `Each loss reason must be one of: ${reasonList.join(', ')}.` };
} else if (!yesNoUnknown.includes(doorOpen)) {
  error = { code: 'INVALID_DOOR_OPEN', message: 'Door open must be yes, no, or unknown.' };
} else if (nextTouch !== '' && !validDate(nextTouch)) {
  error = { code: 'INVALID_NEXT_TOUCH', message: 'The next-touch date must use YYYY-MM-DD or be empty.' };
}

const actionId = error ? '' : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => { const random = Math.floor(Math.random() * 16); const value = character === 'x' ? random : (random & 0x3) | 0x8; return value.toString(16); });
const confirmationText = error ? '' : `CONFIRM ${actionId.replaceAll('-', '').slice(-8).toUpperCase()}`;
const expiresAt = error ? '' : new Date(Date.now() + 5 * 60 * 1000).toISOString();
return {
  json: {
    valid: error === null,
    sessionId,
    actionId,
    actionType: 'log_lost_lead',
    proposedInput,
    confirmationText,
    expiresAt,
    ...(error ? { response: { ok: false, error } } : {})
  }
};

const proposal = $('Validate Proposal').first().json;
if (!Number.isInteger($json.id)) {
  return {
    json: {
      ...proposal,
      response: {
        ok: false,
        error: {
          code: 'CONFIRMATION_DATA_UNAVAILABLE',
          message: 'The proposal could not be saved. Rerun local setup, then try again.'
        }
      }
    }
  };
}
return {
  json: {
    ...proposal,
    response: {
      ok: true,
      confirmationRequired: true,
      action: { type: 'log_lost_lead', arguments: proposal.proposedInput },
      confirmation: {
        phrase: proposal.confirmationText,
        expiresAt: proposal.expiresAt
      },
      message: `No record changed. Ask the user to reply with exactly "${proposal.confirmationText}" within five minutes.`
    }
  }
};

const response = $json.response;
const proposedInput = $json.proposedInput ?? {};
return {
  json: {
    occurredAt: new Date().toISOString(),
    sessionId: String($json.sessionId ?? ''),
    requestId: String($json.actionId ?? $json.requestId ?? ''),
    toolName: 'log_lost_lead_proposal',
    proposedInput: JSON.stringify(proposedInput),
    result: JSON.stringify(response),
    error: response?.ok === false ? String(response.error?.message ?? 'Tool call failed') : '',
    response
  }
};

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
